class PaymentService {
  constructor() {
    this.processed = 0;
  }
  charge(job) {
    this.processed += 1;
    return `charged ${job.orderId}`;
  }
}

function runJobs(jobs, handler) {
  return jobs.map((job) => {
    try {
      return handler(job);
    } catch (error) {
      return "failed";
    }
  });
}

const payments = new PaymentService();
console.log(runJobs([{ orderId: "ORD-7" }, { orderId: "ORD-8" }], payments.charge), payments.processed);

