function myBind(fn, thisValue, ...fixedArgs) {
  return (...laterArgs) => fn.apply(thisValue, [...fixedArgs, ...laterArgs]);
}

function fee(percent, amount) {
  return `${this?.bank}: ${(amount * percent) / 100}`;
}

const gtFee = myBind(fee, { bank: "GT" }, 2);
console.log(gtFee(5000));
console.log(gtFee.call({ bank: "Other" }, 1000));

