questions.solution:
function bindMethods(obj, names) {
  for (const name of names) obj[name] = obj[name].bind(obj);
  return obj;
}

const cart = {
  items: [],
  add(sku) {
    this.items.push(sku);
  },
  size() {
    return this.items.length;
  },
};

const { add, size } = bindMethods(cart, ["add", "size"]);
try {
  add("RICE-5");
  add("OIL-1");
  console.log(size());
} catch (error) {
  console.log(error.name);
}
